<script setup lang="ts">
import { Crosshair,RotateCw,Repeat2,Zap,Users } from '@lucide/vue'
import ThumbStick from '@/components/hud/ThumbStick.vue'
import { settings } from '@/stores/profile'
import type { GameState } from '@/types/game'
const props=defineProps<{state:Readonly<GameState>}>();const emit=defineEmits<{move:[x:number,y:number];release:[];aim:[x:number,y:number];aimrelease:[];fire:[pressed:boolean];pulse:[];reload:[];cycle:[];squad:[]}>()
function fireDown(e:PointerEvent){(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);emit('fire',true)}
</script>
<template><div class="touch-sticks" :class="{swapped:settings.leftHanded}" :style="{'--control-offset':`${settings.controlOffset}px`}"><ThumbStick :size="settings.controlSize" @move="(x,y)=>emit('move',x,y)" @release="emit('release')"/><ThumbStick aim :size="settings.controlSize" @move="(x,y)=>emit('aim',x,y)" @release="emit('aimrelease')"/></div><div class="combat-actions"><button data-testid="fire-button" class="fire-button" aria-label="Disparar" @pointerdown="fireDown" @pointerup="emit('fire',false)" @pointercancel="emit('fire',false)" @lostpointercapture="emit('fire',false)"><Crosshair :size="21"/><span>FUEGO</span></button><button data-testid="reload-button" :disabled="(props.state.reload||0)>0" aria-label="Recargar" @click="emit('reload')"><RotateCw :size="20"/><span>{{(props.state.reload||0)>0?'…':'RECARGA'}}</span><kbd>R</kbd></button><button data-testid="cycle-weapon" aria-label="Cambiar arma" @click="emit('cycle')"><Repeat2 :size="20"/><span>ARMA</span><kbd>Q</kbd></button><button data-testid="pulse-button" :disabled="props.state.pulseCooldown>0" aria-label="Pulso defensivo" @click="emit('pulse')"><Zap :size="21"/><span>{{props.state.pulseCooldown>0?`${Math.ceil(props.state.pulseCooldown)} s`:'PULSO'}}</span><kbd>ESPACIO</kbd></button><button data-testid="squad-button" :disabled="!props.state.signals||(props.state.squadCooldown||0)>0" aria-label="Convocar escuadra" @click="emit('squad')"><Users :size="21"/><span>{{(props.state.squadTime||0)>0?`${Math.ceil(props.state.squadTime!)} s`:(props.state.squadCooldown||0)>0?`${Math.ceil(props.state.squadCooldown!)} s`:`ECO · ${props.state.signals||0}`}}</span><kbd>E</kbd></button></div><div class="keyboard-hint"><kbd>W A S D</kbd> MUÉVETE <i/> <kbd>RATÓN</kbd> APUNTA <i/> <kbd>1 – 8</kbd> ARSENAL</div></template>
